tests.test_code:
run jq -c -f etl.jq << 'END_INPUT'
    {
      "legacy": {
        "1": [
          "A"
        ]
      }
    }
END_INPUT

assert_success
expected='{"a":1}'
assert_objects_equal "$output" "$expected"

run jq -c -f etl.jq << 'END_INPUT'
    {
      "legacy": {
        "1": [
          "A",
          "E",
          "I",
          "O",
          "U"
        ]
      }
    }
END_INPUT

assert_success
expected='{"a":1,"e":1,"i":1,"o":1,"u":1}'
assert_objects_equal "$output" "$expected"

run jq -c -f etl.jq << 'END_INPUT'
    {
      "legacy": {
        "1": [
          "A",
          "E"
        ],
        "2": [
          "D",
          "G"
        ]
      }
    }
END_INPUT

assert_success
expected='{"a":1,"d":2,"e":1,"g":2}'
assert_objects_equal "$output" "$expected"
